int minimumDifference(std::vector<int> a) {
    std::sort(a.begin(), a.end());
    int best = INT_MAX;
    for (size_t i = 0; i + 1 < a.size(); i++) best = std::min(best, a[i + 1] - a[i]);
    return best;
}

std::vector<int> waveForm(std::vector<int> a) {
    std::sort(a.begin(), a.end());
    for (size_t i = 0; i + 1 < a.size(); i += 2) std::swap(a[i], a[i + 1]);
    return a;
}

long long maxIndexSum(std::vector<int> a) {
    std::sort(a.begin(), a.end());       // biggest value, biggest index
    long long total = 0;
    for (size_t i = 0; i < a.size(); i++) total += (long long)i * a[i];
    return total;
}

int maxWins(std::vector<int> mine, std::vector<int> theirs) {
    std::sort(mine.begin(), mine.end());
    std::sort(theirs.begin(), theirs.end());
    int wins = 0;
    size_t i = 0;
    for (size_t j = 0; j < theirs.size() && i < mine.size(); j++) {
        // Units too weak here cannot beat any later enemy either.
        while (i < mine.size() && mine[i] <= theirs[j]) i++;
        if (i < mine.size()) { wins++; i++; }
    }
    return wins;
}

long long minimumMoves(std::vector<int> people, std::vector<int> chairs) {
    std::sort(people.begin(), people.end());
    std::sort(chairs.begin(), chairs.end());
    long long total = 0;
    for (size_t i = 0; i < people.size(); i++) total += std::abs(people[i] - chairs[i]);
    return total;
}
